(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-635":{scenario:{company:"Hải Đăng MEP Services",supervisor:{name:"Phan Thị Mỹ Linh",role:{vi:"Trưởng bộ phận Cơ điện & PCCC",en:"Head of MEP & Fire Protection"}},ref_code:"FP-0419",title:{vi:"Bơm luôn sẵn sàng. Điểm đặt đúng. Biên bản trung thực.",en:"Pumps always ready. Setpoints right. Records honest."},brief:{vi:"Bạn soát xét biên bản chạy thử FP-0419 của cụm bơm chữa cháy sprinkler tại một trung tâm thương mại sau bảo trì. Bơm chính điện FP-01 có áp lực ngắt (churn) 9,6 bar; áp lực tĩnh tối thiểu phía hút 1,2 bar. Bản nháp để tủ bơm chính ở chế độ tay và đặt áp lực khởi động bơm chính trùng với bơm bù. Hãy sửa chế độ tủ điều khiển và áp lực khởi động bơm chính (bar), rồi lập báo cáo có căn cứ.",en:"You are reviewing test record FP-0419 for the sprinkler fire pump set of a shopping centre after maintenance. Electric main pump FP-01 has a churn pressure of 9.6 bar; the minimum static suction pressure is 1.2 bar. The draft leaves the main pump controller in manual mode and sets the main pump start pressure equal to the jockey pump start. Correct the controller mode and the main pump start pressure (bar), then write an evidence-based report."},reference_title:{vi:"Quy trình bàn giao PCCC & bảng điểm đặt áp lực đã duyệt",en:"Approved fire handover procedure & pressure setpoint sheet"},fields:[{id:"CTRL_MODE",label:{vi:"Chế độ tủ điều khiển bơm chính FP-01",en:"FP-01 main pump controller mode"},initial:"MANUAL",expected:"AUTO",choices:["AUTO","MANUAL","OFF"],reference:"Quy trình bàn giao hệ thống PCCC",ref_value:{vi:"Sau bảo trì, bơm chữa cháy phải tự khởi động khi áp lực mạng giảm; chế độ tay chỉ dùng khi có phiếu tạm ngừng",en:"After maintenance fire pumps must start on pressure drop; manual mode only under an impairment permit"},hint:{vi:"Ở chế độ tay, bơm chính không tự chạy khi đầu phun mở; hệ thống mất khả năng chữa cháy tự động.",en:"In manual mode the main pump will not start when a sprinkler opens; automatic protection is lost."}},{id:"START_BAR",label:{vi:"Áp lực khởi động bơm chính (bar)",en:"Main pump start pressure (bar)"},initial:"10.1",expected:"9.75",reference:"Bảng điểm đặt áp lực bơm",ref_value:{vi:"Áp lực churn FP-01 9,6 bar; áp lực tĩnh phía hút tối thiểu 1,2 bar",en:"FP-01 churn pressure 9.6 bar; minimum static suction pressure 1.2 bar"},hint:{vi:"Bản nháp cho bơm chính khởi động cùng mức với bơm bù; cần lùi thêm một bậc theo SOP 3.2.",en:"The draft starts the main pump at the jockey start level; step down once more per SOP 3.2."}}],sop32:{vi:"Áp lực dừng bơm bù = áp lực churn bơm chính + áp lực tĩnh hút tối thiểu; bơm bù khởi động thấp hơn mức dừng 0,7 bar; bơm chính khởi động thấp hơn mức khởi động bơm bù 0,35 bar (số liệu mô phỏng).",en:"Jockey stop = main pump churn + minimum static suction; jockey start = 0.7 bar below jockey stop; main pump start = 0.35 bar below jockey start (simulated values)."},context:{label:"BMS / FP-0419",metrics:[{label:{vi:"Định mức FP-01",en:"FP-01 rating"},value:"2,000 L/min @ 8.0 bar"},{label:{vi:"Áp lực churn",en:"Churn pressure"},value:"9.6 bar"},{label:{vi:"Số lần bơm bù chạy",en:"Jockey pump starts"},value:"46 / h"}]},terminal:{system:"fire-pump-ctl",settable:["CTRL_MODE","START_BAR"],commands:[{cmd:"status",out:{vi:"FP-01 (bơm chính điện): MANUAL; JP-01 (bơm bù): AUTO; áp lực mạng hiện tại 10,6 bar",en:"FP-01 (electric main pump): MANUAL; JP-01 (jockey pump): AUTO; current system pressure 10.6 bar"}},{cmd:"cat setpoints.cfg",out:{vi:"JP-01 dừng 10,8 bar, khởi động 10,1 bar; FP-01 khởi động 10,1 bar (trùng bơm bù)",en:"JP-01 stop 10.8 bar, start 10.1 bar; FP-01 start 10.1 bar (same as jockey)"}},{cmd:"cat pump-curve.txt",out:{vi:"FP-01: định mức 2 000 L/phút tại 8,0 bar; áp lực churn 9,6 bar; tại 150% lưu lượng còn 5,6 bar",en:"FP-01: rated 2,000 L/min at 8.0 bar; churn 9.6 bar; 5.6 bar at 150% flow"}},{cmd:"cat suction.txt",out:{vi:"Bể nước chữa cháy: áp lực tĩnh tối thiểu tại đầu hút 1,2 bar",en:"Fire water tank: minimum static pressure at the suction 1.2 bar"}},{cmd:"cat event.log",out:{vi:"02:10 mở van xả thử: áp giảm còn 9,4 bar, FP-01 không khởi động (MANUAL); JP-01 chạy 46 lần mỗi giờ",en:"02:10 test valve opened: pressure fell to 9.4 bar, FP-01 did not start (MANUAL); JP-01 cycled 46 times per hour"}}]},crisis:{vi:"Trưởng ban quản lý tòa nhà: “Để AUTO thì bơm bù chạy liên tục, khách thuê kêu ồn. Cứ để MANUAL, biên bản ghi AUTO cho đoàn kiểm tra PCCC sáng mai, có cháy thì bảo vệ xuống bật tay.”",en:"The building manager: “On AUTO the jockey pump runs nonstop and tenants complain about noise. Leave it on MANUAL, write AUTO in the record for tomorrow's fire inspection; in a fire, security can start it by hand.”"},options:{safe:{vi:"Không ghi sai biên bản; đặt lại điểm đặt, chuyển AUTO và xử lý rò rỉ làm bơm bù chạy liên tục; báo trưởng bộ phận, chủ đầu tư; nếu phải tạm ngừng thì lập phiếu suy giảm hệ thống và trực cháy.",en:"Do not falsify the record; reset the setpoints, switch to AUTO and fix the leak behind the jockey cycling; inform the department head and owner; if shutdown is needed, use an impairment permit and fire watch."},shortcut:{vi:"Để MANUAL cho yên tĩnh, ghi AUTO vào biên bản và dặn bảo vệ bật tay khi có cháy.",en:"Leave it on MANUAL for quiet, write AUTO in the record and tell security to start it by hand in a fire."},wait:{vi:"Giữ nguyên hiện trạng, không ký biên bản và chờ ban quản lý tự quyết định.",en:"Leave things as they are, do not sign and wait for building management to decide."}},questions:{vi:["Giải thích chuỗi điểm đặt áp lực bạn đã tính và vì sao bơm chính không được khởi động cùng mức với bơm bù.","Để hệ thống chữa cháy ở chế độ tay gây rủi ro gì, và quy trình tạm ngừng hệ thống hợp lệ gồm những bước nào?"],en:["Explain the pressure setpoint sequence you calculated and why the main pump must not start at the jockey level.","What risks arise from leaving fire pumps in manual, and what steps make a valid system impairment procedure?"]},hints:{vi:["Chạy lệnh xem trạng thái và nhật ký sự kiện, đối chiếu với quy trình bàn giao trước khi sửa.","Theo SOP mục 3.2, tính mức dừng bơm bù trước, rồi lần lượt trừ các khoảng chênh để ra mức khởi động bơm chính.","SOP mục 4.2: biên bản PCCC phải phản ánh đúng trạng thái thực; đề nghị ghi sai phải báo cấp có thẩm quyền."],en:["Run the status and event log commands and compare them with the handover procedure before editing.","Under SOP 3.2, compute the jockey stop first, then subtract each differential to reach the main pump start.","SOP 4.2: fire records must show the real status; escalate any request to falsify them to the competent authority."]}},learning:{summary:{vi:"Kỹ sư cơ điện công trình (MEP) thiết kế, giám sát lắp đặt, chạy thử và vận hành các hệ thống điều hòa thông gió, cấp thoát nước và phòng cháy chữa cháy. Họ bảo đảm công trình tiện nghi, tiết kiệm năng lượng và an toàn cháy, phối hợp chặt với kiến trúc, kết cấu và nhà thầu. Nghề đòi hỏi kiến thức nhiệt lạnh, thủy lực, điều khiển, hiểu quy chuẩn an toàn cháy và kỷ luật trong thử nghiệm, nghiệm thu.",en:"An MEP engineer designs, supervises installation, commissions and operates HVAC, plumbing and fire fighting systems. They make buildings comfortable, energy efficient and fire safe, working closely with architecture, structure and contractors. The role requires knowledge of refrigeration, hydraulics and controls, command of fire safety codes and discipline in testing and acceptance."},responsibilities:{vi:["Tính toán tải lạnh, lưu lượng gió, nước cấp, nước thoát và lưu lượng chữa cháy cho công trình.","Thiết kế, chọn thiết bị: chiller, AHU, bơm, đường ống, đầu phun sprinkler, tủ điều khiển.","Phối hợp không gian kỹ thuật, cao độ đường ống với kiến trúc, kết cấu trên mô hình BIM.","Giám sát lắp đặt, thử áp, chạy thử, cân chỉnh (T&C) và lập hồ sơ nghiệm thu.","Hướng dẫn vận hành, bảo trì và xử lý sự cố hệ thống cơ điện, PCCC."],en:["Calculate cooling loads, airflow, water supply, drainage and fire water demand.","Design and select equipment: chillers, AHUs, pumps, piping, sprinkler heads and controllers.","Coordinate plant space and pipe levels with architecture and structure in the BIM model.","Supervise installation, pressure tests and testing and commissioning (T&C) and compile acceptance records.","Train operators, plan maintenance and troubleshoot MEP and fire systems."]},competencies:[{name:{vi:"Nhiệt lạnh & thông gió",en:"HVAC design"},desc:{vi:"Tính tải lạnh, cân bằng gió, lựa chọn hệ thống điều hòa hiệu quả năng lượng.",en:"Calculate cooling loads, balance air and select energy-efficient air conditioning systems."}},{name:{vi:"Thủy lực & bơm",en:"Hydraulics & pumps"},desc:{vi:"Tính tổn thất áp, chọn bơm theo đường đặc tính và thiết lập điểm đặt điều khiển.",en:"Compute pressure losses, select pumps from their curves and set control setpoints."}},{name:{vi:"Phòng cháy chữa cháy",en:"Fire protection"},desc:{vi:"Thiết kế sprinkler, họng nước, bơm chữa cháy theo quy chuẩn và hồ sơ thẩm duyệt.",en:"Design sprinklers, hose reels and fire pumps to code and the approved fire design."}},{name:{vi:"Chạy thử & cân chỉnh",en:"Testing & commissioning"},desc:{vi:"Lập quy trình T&C, đo kiểm, so sánh với thiết kế và xử lý sai lệch.",en:"Write T&C procedures, measure, compare with design and resolve deviations."}},{name:{vi:"An toàn & trung thực",en:"Safety & integrity"},desc:{vi:"Không vô hiệu hóa hệ thống an toàn, ghi biên bản đúng thực tế.",en:"Never disable life safety systems and record test results truthfully."}}],knowledge:{vi:["QCVN 06:2022/BXD - Quy chuẩn kỹ thuật quốc gia về an toàn cháy cho nhà và công trình, kèm sửa đổi 1:2023.","TCVN 7336:2021 - Phòng cháy chữa cháy: hệ thống sprinkler tự động, yêu cầu thiết kế và lắp đặt.","TCVN 5687 (phiên bản hiện hành) - Thông gió, điều hòa không khí: tiêu chuẩn thiết kế.","NFPA 20 - Tiêu chuẩn lắp đặt bơm cố định cho phòng cháy (tham khảo quốc tế).","Nguyên lý thủy lực: đường đặc tính bơm, tổn thất áp, áp lực churn và điểm làm việc."],en:["QCVN 06:2022/BXD - National technical regulation on fire safety of buildings, with Amendment 1:2023.","TCVN 7336:2021 - Fire protection: automatic sprinkler systems, design and installation requirements.","TCVN 5687 (current edition) - Ventilation and air conditioning: design standard.","NFPA 20 - Standard for the installation of stationary pumps for fire protection (international reference).","Hydraulic principles: pump curves, pressure losses, churn pressure and duty point."]},tools:["Phần mềm tính tải lạnh","Phần mềm tính thủy lực sprinkler","Phần mềm mô hình BIM cơ điện","Đồng hồ áp lực và lưu lượng kế","Hệ thống quản lý tòa nhà (BMS)","Máy đo gió và nhiệt ẩm"],kpis:{vi:["Tỷ lệ hệ thống đạt chạy thử nghiệm thu ngay lần đầu.","Số lần hệ thống PCCC mất sẵn sàng (mục tiêu bằng 0).","Chỉ số tiêu thụ năng lượng điều hòa (kWh/m2.năm) so với mục tiêu.","Thời gian xử lý yêu cầu sự cố cơ điện."],en:["Share of systems passing commissioning first time.","Fire system out-of-service events (target zero).","HVAC energy use intensity (kWh/m2.year) against target.","Response time to MEP fault requests."]},day:[{time:"08:00",vi:"Kiểm tra cảnh báo BMS, trạng thái bơm chữa cháy, chiller và bể nước.",en:"Review BMS alarms and the status of fire pumps, chillers and water tanks."},{time:"09:30",vi:"Giám sát thử áp đường ống sprinkler tầng 8, ghi áp lực đầu và cuối thời gian thử.",en:"Witness the level 8 sprinkler pressure test and log start and end pressures."},{time:"13:30",vi:"Phối hợp cao độ ống gió, ống nước với kết cấu và trần trên mô hình liên kết.",en:"Coordinate duct and pipe levels with structure and ceilings in the federated model."},{time:"15:30",vi:"Chạy thử bơm chữa cháy: khởi động tự động, đo lưu lượng, áp lực theo đường đặc tính.",en:"Test fire pumps: automatic start, flow and pressure against the pump curve."},{time:"17:00",vi:"Lập biên bản, cập nhật danh sách tồn tại và kế hoạch khắc phục.",en:"Write the test record and update the defects list and corrective plan."}],mistakes:{vi:["Để tủ bơm chữa cháy ở chế độ tay sau bảo trì, làm hệ thống không tự khởi động.","Đặt áp lực khởi động bơm chính trùng hoặc cao hơn bơm bù, gây chạy sai và hao mòn.","Bỏ qua việc bơm bù chạy liên tục, không tìm rò rỉ trên mạng đường ống."],en:["Leaving fire pump controllers in manual after maintenance so the system cannot start itself.","Setting the main pump start equal to or above the jockey start, causing false starts and wear.","Ignoring a constantly cycling jockey pump instead of finding the leak in the network."]},career:[{vi:"Kỹ thuật viên cơ điện",en:"MEP technician"},{vi:"Kỹ sư thiết kế cơ điện",en:"MEP design engineer"},{vi:"Chủ trì cơ điện dự án",en:"Lead MEP engineer"},{vi:"Giám đốc kỹ thuật cơ điện",en:"MEP technical director"}],glossary:[{term:"Churn pressure",vi:"Áp lực bơm tạo ra khi chạy ở lưu lượng bằng 0, tức khi van xả đóng hoàn toàn.",en:"Pressure a pump develops when running at zero flow with the discharge closed."},{term:"Jockey pump",vi:"Bơm bù áp nhỏ giữ áp lực mạng, tránh bơm chính khởi động do rò rỉ nhỏ.",en:"Small pressure-maintenance pump that prevents the main pump starting on minor leaks."},{term:"Sprinkler",vi:"Đầu phun tự động mở khi nhiệt độ đạt ngưỡng, phun nước dập đám cháy ở giai đoạn đầu.",en:"Automatic head that opens at a set temperature and sprays water on an incipient fire."},{term:"T&C",vi:"Chạy thử và cân chỉnh hệ thống để xác nhận vận hành đúng thiết kế trước khi bàn giao.",en:"Testing and commissioning to confirm systems perform as designed before handover."},{term:"Impairment",vi:"Tình trạng hệ thống PCCC tạm ngừng hoặc suy giảm, phải có phiếu phép và biện pháp bù.",en:"Fire protection system out of service or degraded, requiring a permit and compensating measures."}],quiz:[{q:{vi:"Churn bơm chính 8,0 bar, áp tĩnh hút 1,0 bar. Bơm bù dừng = churn + tĩnh, khởi động thấp hơn 0,7 bar; bơm chính thấp hơn bơm bù 0,35 bar. Áp lực khởi động bơm chính?",en:"Main pump churn 8.0 bar, static suction 1.0 bar. Jockey stop = churn + static, start 0.7 bar lower; main pump 0.35 bar below jockey start. Main pump start?"},options:{vi:["9,00 bar","8,30 bar","7,60 bar","7,95 bar"],en:["9.00 bar","8.30 bar","7.60 bar","7.95 bar"]},answer:3,explain:{vi:"Bơm bù dừng 9,0 bar, khởi động 8,3 bar; bơm chính khởi động 8,3 - 0,35 = 7,95 bar.",en:"Jockey stops at 9.0 bar and starts at 8.3 bar; the main pump starts at 8.3 - 0.35 = 7.95 bar."}},{q:{vi:"Quy chuẩn quốc gia nào quy định an toàn cháy cho nhà và công trình tại Việt Nam?",en:"Which national regulation sets fire safety requirements for buildings in Vietnam?"},options:{vi:["QCVN 06:2022/BXD","QCVN 01:2021/BXD","TCVN 4453:1995","TCVN 9386:2012"],en:["QCVN 06:2022/BXD","QCVN 01:2021/BXD","TCVN 4453:1995","TCVN 9386:2012"]},answer:0,explain:{vi:"QCVN 06:2022/BXD là quy chuẩn an toàn cháy cho nhà và công trình; các văn bản còn lại thuộc quy hoạch, thi công bê tông, động đất.",en:"QCVN 06:2022/BXD is the building fire safety regulation; the others cover planning, concrete works and seismic design."}},{q:{vi:"Ban quản lý đề nghị để bơm chữa cháy ở chế độ tay cho đỡ ồn và ghi AUTO trong biên bản. Bạn làm gì?",en:"Management asks you to keep the fire pump in manual to reduce noise and write AUTO in the record. What do you do?"},options:{vi:["Đồng ý vì đã có bảo vệ trực","Không ghi sai, xử lý nguyên nhân, chuyển AUTO và báo cấp có thẩm quyền","Để AUTO ban đêm, MANUAL ban ngày","Tắt bơm bù cho hết ồn"],en:["Agree because security is on duty","Refuse to falsify, fix the cause, switch to AUTO and inform the authority","AUTO at night, MANUAL by day","Switch off the jockey pump to stop the noise"]},answer:1,explain:{vi:"Hệ thống chữa cháy phải luôn tự động; ghi sai biên bản là vi phạm nghiêm trọng và có thể gây thiệt hại về người.",en:"Fire systems must stay automatic; falsifying records is a serious violation that can cost lives."}},{q:{vi:"Bơm bù khởi động hơn 40 lần mỗi giờ thường là dấu hiệu của vấn đề gì?",en:"A jockey pump starting more than 40 times per hour usually signals what?"},options:{vi:["Bơm chính quá lớn","Áp lực churn quá thấp","Rò rỉ trên mạng đường ống hoặc van","Bể nước quá đầy"],en:["Main pump oversized","Churn pressure too low","A leak in the piping network or valves","Water tank too full"]},answer:2,explain:{vi:"Bơm bù chạy dày cho thấy áp lực mạng sụt liên tục, thường do rò rỉ cần được tìm và xử lý.",en:"Frequent jockey cycling shows the network keeps losing pressure, usually from a leak that must be found and fixed."}}],tools_en:["Cooling load calculation software","Sprinkler hydraulic calculation software","MEP BIM modeling software","Pressure gauges and flow meters","Building management system (BMS)","Anemometer and thermo-hygrometer"]}}})})(window.KKR);
